+static bool detect_runs(uint32_t* a, size_t n) {
+    if (n < 2) return true;
+    bool asc = true, desc = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] < a[i - 1]) asc = false;
+        if (a[i] > a[i - 1]) desc = false;
+        if (!asc && !desc) return false;
+    }
+    if (desc) std::reverse(a, a + n);
+    return true;
