+static void radix_sort_8bit(uint32_t* a, uint32_t* tmp, size_t n) {
+    constexpr int NUM_PASSES = 4;
+    constexpr int SHIFT_AMOUNT = 8;
+    constexpr int BIT_MASK = 0xFF;
+    constexpr int HIST_SIZE = 256;
+    
+    for (int pass = 0; pass < NUM_PASSES; ++pass) {
+        uint32_t shift = pass * SHIFT_AMOUNT;
+        
+        // Check if all keys have same digit for this pass
+        uint32_t first_digit = (a[0] >> shift) & BIT_MASK;
+        bool all_same = true;
+        for (size_t i = 1; i < n; ++i) {
+            if (((a[i] >> shift) & BIT_MASK) != first_digit) {
+                all_same = false;
+                break;
