+        }
+        if (all_same) continue;
+        
+        // Count frequencies
+        uint32_t counts[HIST_SIZE] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            counts[(a[i] >> shift) & BIT_MASK]++;
+        }
+        
+        // Compute exclusive scan (prefix sums)
+        uint32_t positions[HIST_SIZE];
+        uint32_t sum = 0;
+        for (int k = 0; k < HIST_SIZE; ++k) {
+            positions[k] = sum;
+            sum += counts[k];
