+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (a[i] >> shift) & BIT_MASK;
+            tmp[positions[digit]++] = a[i];
+        }
+        
+        // Copy back
+        std::memcpy(a, tmp, n * sizeof(uint32_t));
